WITH with_gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM web_events), sessions_web_events AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT CASE WHEN is_new_burst >= 1 THEN 'LARGE' ELSE 'SMALL' END AS is_new_burst_tier, DATE_TRUNC('QUARTER', event_time) AS quarter_start, page, ROUND(SUM(session_no) / NULLIF(COUNT(CASE WHEN event_type = 'page_view' THEN 1 END), 0), 2) AS session_no_per_page_view, SORT_ARRAY(COLLECT_SET(page)) AS page_list, COUNT(*) AS row_count FROM sessions_web_events GROUP BY 1, 2, 3 HAVING COUNT(*) < 1000 ORDER BY quarter_start DESC;
